using System;using System.IO;using System.Drawing;using System.Windows.Forms;
namespace FleetLab
{
    internal static class PracticeReinforcementPauseFormChecks
    {
        static T C<T>(Form f,string n)where T:Control{return(T)f.Controls.Find(n,true)[0];}static void Need(bool v,string m){if(!v)throw new Exception(m);}static void Click(Form f,string n){C<Button>(f,n).PerformClick();Application.DoEvents();}static void Show(Form f,Form owner){f.Show(owner);Application.DoEvents();}
        internal static void Run(Action<string,Action> check,string assets,Form owner)
        {
            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");
            check("Pause-wave window starts compensated negative profile and distinguishes old40 from new160 delta",delegate{using(var parent=new PracticeGeneratedReinforcementStudy(programs))using(var f=new PracticeReinforcementPhaseStudy(programs,true,true)){Need(parent.Controls.Find("generatedPauseWaves",true).Length==1,"Discoverable compensated mode");Show(f,owner);Need(f.ClockSnapshot.AppliesPauseCompensation&&f.StateSnapshot.PauseProfile==2,"Explicit default compensated profile");Click(f,"phaseWave32");Click(f,"phaseWaveStep");Need(f.ShownClockUpdate.BodyClock.DeltaMilliseconds==40&&f.ClockSnapshot.Clock.DeltaMilliseconds==160&&f.StateSnapshot.World.NextDeadline==f.StateSnapshot.FirstDeadline+40,"First paused tail precedes epilogue");Need(C<TextBox>(f,"phaseWaveDetails").Text.Contains("applied OLD delta 40ms"),"Olddelta visible");}});
            check("Pause-wave window displays cumulative200 then240 and preserves pending reset versus Load",delegate{using(var f=new PracticeReinforcementPhaseStudy(programs,true,true)){Show(f,owner);Click(f,"phaseWave32");Click(f,"phaseWaveStep");Click(f,"phaseWaveStep");Need(f.ShownClockUpdate.BodyClock.DeltaMilliseconds==160&&f.StateSnapshot.World.NextDeadline==f.StateSnapshot.FirstDeadline+200,"Second tail old160");Click(f,"phaseWaveStep");Need(f.ClockSnapshot.PauseTimers.GlobalCounter==224&&f.StateSnapshot.World.NextDeadline==f.StateSnapshot.FirstDeadline+240,"Third tail total240 anduintwrap");C<ComboBox>(f,"phaseWavePause").SelectedIndex=0;Click(f,"phaseWaveReset");Need(f.StateSnapshot.PauseProfile==2&&f.StateSnapshot.Frames==0&&C<Label>(f,"phaseWavePending").Text.Contains("pending"),"Reset preserves applied compensated profile");f.StudyKey(Keys.Enter,false);f.StudyKey(Keys.Enter,true);Need(f.StateSnapshot.PauseProfile==0,"Enter applies pending unpaused profile");C<ComboBox>(f,"phaseWaveSeed").SelectedIndex=1;f.StudyKey(Keys.Enter,true);Need(f.StateSnapshot.World.InitialSeed==731,"HeldEnter suppressed");f.StudyKey(Keys.Enter,false);f.StudyKey(Keys.Enter,true);f.StudyKey(Keys.Enter,false);Need(f.StateSnapshot.World.InitialSeed==0,"Newpress applies pendingseed");}});
            check("Pause-wave trace retains seven births and one pending wave while inspecting zero frame67",delegate{using(var f=new PracticeReinforcementPhaseStudy(programs,true,true)){Show(f,owner);Click(f,"phaseWaveFinish");Need(f.StateSnapshot.Frames==96&&f.StateSnapshot.World.CreatedFleetCount==7&&f.StateSnapshot.World.PendingEvents==1&&!C<Button>(f,"phaseWaveStep").Enabled,"Bounded checkpoint is not all waves complete");C<DataGridView>(f,"phaseWaveTrace").CurrentCell=C<DataGridView>(f,"phaseWaveTrace").Rows[66].Cells[0];Application.DoEvents();Need(f.ShownSnapshot.Frames==67&&f.ShownSnapshot.World.LastCreated.Count==7&&f.ShownClockUpdate.ZeroInterval&&f.ShownClockUpdate.State.Clock.GameMilliseconds==1&&f.StateSnapshot.Frames==96,"Historical pre-epilogue birth andcompletedclock");Need(C<TextBox>(f,"phaseWaveDetails").Text.Contains("total shift 240ms"),"Selectedframe compensated timers shown");}});
            check("Pause-wave minimum layout scrolls opaque timer details with fixed Close and clean disposal",delegate{using(var f=new PracticeReinforcementPhaseStudy(programs,true,true)){Show(f,owner);Click(f,"phaseWaveFinish");f.ClientSize=new Size(940,620);var d=C<TextBox>(f,"phaseWaveDetails");d.Focus();C<Panel>(f,"phaseWaveScroll").ScrollControlIntoView(d);Application.DoEvents();var close=C<Button>(f,"phaseWaveClose");Need(d.Width>=860&&f.ClientRectangle.Contains(new Rectangle(f.PointToClient(close.PointToScreen(Point.Empty)),close.Size)),"Scrollable detailed clock/timer view andfixedClose");Click(f,"phaseWaveClose");Need(f.IsDisposed||!f.Visible,"Populated compensated history closes cleanly");}});
        }
        static void Save(Form f,string o,string n){Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.Size));b.Save(Path.Combine(o,n+".png"),System.Drawing.Imaging.ImageFormat.Png);}}
        internal static int SavePreviews(string assets,string output)
        {
            try{Directory.CreateDirectory(output);using(var f=new PracticeReinforcementPhaseStudy(Path.Combine(Path.GetDirectoryName(assets),"Programs"),true,true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();Save(f,output,"01-initial");Click(f,"phaseWave32");Save(f,output,"02-equality32");Click(f,"phaseWaveStep");Save(f,output,"03-old40-new160");Click(f,"phaseWaveStep");Save(f,output,"04-old160-total200");Click(f,"phaseWaveStep");Save(f,output,"05-total240");Click(f,"phaseWaveFinish");C<DataGridView>(f,"phaseWaveTrace").CurrentCell=C<DataGridView>(f,"phaseWaveTrace").Rows[66].Cells[0];Application.DoEvents();Save(f,output,"06-zero67-seven-births");C<DataGridView>(f,"phaseWaveTrace").CurrentCell=C<DataGridView>(f,"phaseWaveTrace").Rows[95].Cells[0];Application.DoEvents();Save(f,output,"07-final-one-pending");f.ClientSize=new Size(940,620);var d=C<TextBox>(f,"phaseWaveDetails");d.Focus();C<Panel>(f,"phaseWaveScroll").ScrollControlIntoView(d);Save(f,output,"08-minimum-details");f.Close();}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"Error.txt"),ex.ToString());return 1;}
        }
    }
}
